    VocabEntry("b1_22", "allergic", "/əˈlɜːrdʒɪk/", "alérgico", "Salud", LearnerLevel.INTERMEDIO, "Are you allergic to anything?", "¿Eres alérgico a algo?", "Siempre usa 'allergic to...'."),
