    VocabEntry("b1_26", "confident", "/ˈkɑːnfɪdənt/", "seguro de sí mismo", "Emociones", LearnerLevel.INTERMEDIO, "You sound much more confident now.", "Suenas mucho más seguro ahora.", "Falso amigo: 'confidente' es 'confidant'."),
